INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Welche Hauptaufgabe hat die DCL in einer Datenbank?', 2, '[{"text": "Zugriffsrechte definieren", "correct": true, "because": "DCL steuert Berechtigungen"}, {"text": "Daten einfügen", "correct": false, "because": "DML-Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher DCL-Befehl vergibt Berechtigungen?', 3, '[{"text": "GRANT", "correct": true, "because": "Vergibt Zugriffsrechte"}, {"text": "REVOKE", "correct": false, "because": "Entzieht Rechte"}, {"text": "ALTER", "correct": false, "because": "DDL-Befehl"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rechte kann man mit DCL verwalten?', 5, '[{"text": "SELECT", "correct": true, "because": "Leserechte"}, {"text": "INSERT", "correct": true, "because": "Schreibrechte"}, {"text": "CREATE", "correct": false, "because": "DDL-Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DCL schützt Datenbankobjekte. b) Sie verändert Tabellenstrukturen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist DDL"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung von DCL?', 4, '[{"text": "Benutzerrollen", "correct": false, "because": "Wichtig für Verwaltung"}, {"text": "Berechtigungsstufen", "correct": false, "because": "Definiert Zugriff"}, {"text": "Monitorauflösung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein DCL-Befehl Daten löschen?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Zugriffssteuerung"}, {"text": "Ja", "correct": false, "because": "DML-Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl entzieht Berechtigungen in SQL?', 3, '[{"text": "REVOKE", "correct": true, "because": "Entfernt Zugriffsrechte"}, {"text": "DENY", "correct": false, "because": "Spezifisch für SQL Server"}, {"text": "DROP", "correct": false, "because": "DDL-Befehl"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Objekte können mit DCL geschützt werden?', 5, '[{"text": "Tabellen", "correct": true, "because": "Häufigster Anwendungsfall"}, {"text": "Views", "correct": true, "because": "Auch Zugriff steuerbar"}, {"text": "Hardware", "correct": false, "because": "Kein Datenbankobjekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) DCL ist Teil von SQL. b) Sie definiert Tabellen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist DDL"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für DCL?', 4, '[{"text": "Benutzerkonten", "correct": false, "because": "Rechte werden vergeben"}, {"text": "Datenbankobjekte", "correct": false, "because": "Ziel der Steuerung"}, {"text": "Küchenzeile", "correct": true, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann DCL Datenbankstrukturen ändern?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Zugriffskontrolle"}, {"text": "Ja", "correct": false, "because": "DDL-Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Berechtigungen kann GRANT vergeben?', 4, '[{"text": "UPDATE", "correct": true, "because": "Änderungsrechte"}, {"text": "DELETE", "correct": true, "because": "Löschrechte"}, {"text": "FORMAT", "correct": false, "because": "Kein Berechtigungstyp"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass DCL nur für Administratoren ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Jeder mit Rechten kann nutzen"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei DCL?', 3, '[{"text": "Sicherheitsrichtlinien", "correct": true, "because": "Schutz gewährleisten"}, {"text": "Schnelle Ausführung", "correct": false, "because": "Sorgfalt wichtiger"}, {"text": "Minimale Rechte", "correct": false, "because": "Kontextabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DCL hilft bei der Zugriffskontrolle. b) Sie fügt Daten ein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist DML"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rollen können mit DCL verwaltet werden?', 5, '[{"text": "Benutzer", "correct": true, "because": "Individuelle Rechte"}, {"text": "Gruppen", "correct": true, "because": "Rollenbasierte Steuerung"}, {"text": "Hardware", "correct": false, "because": "Kein Zugriffsobjekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei DCL unwichtig?', 3, '[{"text": "Berechtigungsprüfung", "correct": false, "because": "Sicherheitskern"}, {"text": "Objektzugriff", "correct": false, "because": "Ziel der Steuerung"}, {"text": "Tastaturtyp", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann DCL Datenbankobjekte erstellen?', 3, '[{"text": "Nein", "correct": true, "because": "Nur Zugriffskontrolle"}, {"text": "Ja", "correct": false, "because": "DDL-Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein DCL-Befehl rückgängig gemacht werden?', 2, '[{"text": "Ja", "correct": true, "because": "REVOKE widerruft GRANT"}, {"text": "Nein", "correct": false, "because": "Flexibel anpassbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt DCL in der Sicherheit?', 4, '[{"text": "Schützt Daten", "correct": true, "because": "Beschränkt Zugriff"}, {"text": "Erhöht Bandbreite", "correct": false, "because": "Kein Netzwerkeffekt"}, {"text": "Verbessert Grafik", "correct": false, "because": "Irrelevant"}]');
